// verify:plugin — proves the shipped business-shell Desktop plugin is loadable by
// the REAL target Hermes, not by any local reproduction of the loader.
//
// Two anchors, both derived from official source:
//   1. A checked-in contract snapshot (scripts/hermes-desktop-contract.json)
//      generated by gen-hermes-contract.mjs from installed Hermes 0.19.1 source
//      — the network-free reference used on clean build machines.
//   2. The installed Hermes Desktop source itself, resolved via
//      electron/paths.cjs (hermesHome). When present it is authoritative: the
//      version must be in range and every SDK symbol / host door / PluginContext
//      method / contribution area / loader+discovery fact our plugin.js relies on
//      must exist in it, or this FAILS CLOSED.
//
// It NEVER cites scripts/lib/probes/hermes/plugin-*.mjs (the fast unit contract
// harness) as evidence of loading. With --release, the installed real source is
// mandatory and must match the snapshot byte-for-byte (sha256), so a release can
// never be cut against drifted or absent Hermes source.

import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { HERMES_COMPAT_RANGE, SDK_SYMBOLS } from './plugin-sdk-contract.mjs'
import {
  CONTRACT_FILES,
  checkRequirements,
  contractFilePath,
  extractPluginRequirements,
  fileSha256,
  readContractSources,
  readInstalledVersion,
  versionInRange
} from './lib/hermes-desktop-contract.mjs'

const releaseMode = process.argv.includes('--release')
const require = createRequire(import.meta.url)
const repoRoot = path.resolve(fileURLToPath(new URL('..', import.meta.url)))
const rel = p => path.join(repoRoot, p)
const { hermesHome } = require(rel('electron/paths.cjs'))

const source = readFileSync(rel('hermes-plugin/business-shell/plugin.js'), 'utf8')
const bootstrapSkill = readFileSync(rel('hermes-plugin/business-shell/skills/business-bootstrap/SKILL.md'), 'utf8')
const welcomeSkill = readFileSync(rel('hermes-plugin/business-shell/skills/tachles-welcome/SKILL.md'), 'utf8')
const snapshot = JSON.parse(readFileSync(rel('scripts/hermes-desktop-contract.json'), 'utf8'))
const failures = []

// ---- 1. Structural plugin contract (static) ---------------------------------
if (!source.includes("from '@hermes/plugin-sdk'")) failures.push('missing official @hermes/plugin-sdk import')
if (!source.includes("id: 'business-shell'")) failures.push('plugin id is missing')
if (!source.includes('ROUTES_AREA')) failures.push('route contribution is missing')
if (!source.includes('SIDEBAR_NAV_AREA')) failures.push('sidebar contribution is missing')
if (!source.includes('business-bootstrap')) failures.push('business onboarding Skill is not referenced')
if (!source.includes('tachles-welcome')) failures.push('guided first-run Skill is not referenced')
if (source.match(/from ['"](@\/|electron|fs|node:)/)) failures.push('plugin imports a forbidden module')
if (/<[A-Z][A-Za-z]*[ >]/.test(source)) failures.push('disk plugin contains JSX, which Hermes does not compile')
if (!bootstrapSkill.includes('name: business-bootstrap')) failures.push('business-bootstrap Skill metadata is missing')
if (!bootstrapSkill.includes('Ask one question at a time')) failures.push('business-bootstrap lacks progressive questions')
if (!bootstrapSkill.includes('Never request API keys')) failures.push('business-bootstrap lacks secret-handling rules')
if (!bootstrapSkill.includes('Recommend one connection')) failures.push('business-bootstrap lacks connection guidance')
// Conversation-first contract: no visible numbered phases, draft->confirm->persist,
// just-in-time connections, first value before optional setup.
if (/^#+\s*Phase\s+\d/im.test(bootstrapSkill)) failures.push('business-bootstrap exposes numbered phases; onboarding must read as one conversation')
if (!/draft/i.test(bootstrapSkill) || !/explicit confirmation/i.test(bootstrapSkill)) failures.push('business-bootstrap lacks the draft -> recap -> explicit confirm -> persist contract')
if (!/stay unknown/i.test(bootstrapSkill)) failures.push('business-bootstrap must keep unconfirmed facts unknown instead of guessing')
if (!/stated goal/i.test(bootstrapSkill)) failures.push('business-bootstrap connections must be intent-led (tied to a stated goal)')
if (!/First value before optional setup/i.test(bootstrapSkill)) failures.push('business-bootstrap must deliver first value before optional setup')
// The first conversation after an install: it senses business vs community from the
// user's own words and hands off, so it must never degrade into a role picker.
if (!welcomeSkill.includes('name: tachles-welcome')) failures.push('tachles-welcome Skill metadata is missing')
const welcomeDescription = (welcomeSkill.match(/^description:\s*(.*)$/m)?.[1] || '').trim().replace(/^['"]|['"]$/g, '')
if (!welcomeDescription) failures.push('tachles-welcome has no routing description')
else if (welcomeDescription.length > 60) {
  failures.push(`tachles-welcome description is ${welcomeDescription.length} chars; Hermes truncates the skill index at 60 and would never route to it`)
}
if (!welcomeSkill.includes('business-bootstrap')) failures.push('tachles-welcome does not hand business work to business-bootstrap')
if (!welcomeSkill.includes('community-bootstrap')) failures.push('tachles-welcome does not hand community work to community-bootstrap')
if (!welcomeSkill.includes('שאל שאלה קצרה אחת בכל פעם')) failures.push('tachles-welcome lacks the one-question-at-a-time rule')
if (!welcomeSkill.includes('זו שיחה, לא אשף')) failures.push('tachles-welcome must state it is a conversation, not a wizard')
if (!welcomeSkill.includes('אל תבקש מהמשתמש לבחור מצב')) failures.push('tachles-welcome must forbid a role picker')
if (/^#+\s*(?:Phase|Step|שלב)\s*\d/im.test(welcomeSkill)) failures.push('tachles-welcome exposes numbered steps; the first run must read as one conversation')
const partnerSkill = readFileSync(rel('hermes-plugin/business-partner/SKILL.md'), 'utf8')
if (!partnerSkill.includes('name: business-partner')) failures.push('business-partner Skill metadata is missing')
if (!/explicit owner approval/i.test(partnerSkill)) failures.push('business-partner lacks the explicit-approval boundary for send/spend/publish/delete')
if (!/do the\s+work directly/i.test(partnerSkill)) failures.push('business-partner must not force delegation for ordinary tasks')
if (!/smallest high-leverage\s+next step/i.test(partnerSkill)) failures.push('business-partner lacks the proactive smallest-next-step posture')

// ---- 2. Live plugin requirements vs the pinned snapshot ---------------------
const req = extractPluginRequirements(source)
const covered = (kind, values) => {
  const pinned = new Set(snapshot.requirements[kind] || [])
  for (const value of values) {
    if (!pinned.has(value)) {
      failures.push(`plugin relies on ${kind} "${value}" not covered by the pinned contract; regenerate scripts/hermes-desktop-contract.json`)
    }
  }
}
covered('sdkSymbols', req.sdkSymbols)
covered('hostMembers', req.hostMembers)
covered('ctxMethods', req.ctxMethods)
covered('areas', req.areas)
// Cross-check the long-standing SDK_SYMBOLS pin still lists every imported symbol.
for (const symbol of req.sdkSymbols) {
  if (!SDK_SYMBOLS.includes(symbol)) failures.push(`plugin imports ${symbol}, absent from the pinned ${HERMES_COMPAT_RANGE} SDK contract`)
}

// ---- 3. Installed real Hermes source (authoritative when present) -----------
const home = hermesHome()
const version = readInstalledVersion(home)
if (version) {
  if (!versionInRange(version, HERMES_COMPAT_RANGE)) {
    failures.push(`installed Hermes ${version} is outside the supported range ${HERMES_COMPAT_RANGE}`)
  } else {
    const sources = readContractSources(home)
    failures.push(...checkRequirements(req, sources))
    if (releaseMode) {
      for (const [relPath, meta] of Object.entries(snapshot.sourceFiles)) {
        let actual = null
        try { actual = fileSha256(contractFilePath(home, meta.key)) } catch { /* missing */ }
        if (actual !== meta.sha256) {
          failures.push(`release: installed ${relPath} sha256 ${actual || 'unreadable'} != snapshot ${meta.sha256}; regenerate the contract from the target release source`)
        }
      }
    }
    console.log(`Verified against installed Hermes ${version} Desktop source (${Object.keys(CONTRACT_FILES).length} contract files).`)
  }
} else if (releaseMode) {
  failures.push(`release: no installed Hermes Desktop source under ${home}; run installer/bootstrap to acquire the official release source before packaging`)
} else {
  console.log(`Installed Hermes source absent; validated against the checked-in real-source snapshot for ${snapshot.generatedFrom.hermesVersion} (contract ${HERMES_COMPAT_RANGE}). This is the pinned contract, not a loader reproduction.`)
}

if (failures.length) {
  console.error(failures.map(item => `- ${item}`).join('\n'))
  process.exit(1)
}
console.log('Desktop plugin contract checks passed.')
